alter table public.companies add column access_status text not null default 'active', add column paused_reason text, add column ai_hourly_limit int not null default 30, add column image_hourly_limit int not null default 30, add column spend_limit_minor bigint, add column ai_cost_minor int not null default 0, add column image_cost_minor int not null default 0;
alter table public.companies add constraint companies_platform_limits check (access_status in ('active','paused') and ai_hourly_limit>=0 and image_hourly_limit>=0 and (spend_limit_minor is null or spend_limit_minor>=0) and ai_cost_minor>=0 and image_cost_minor>=0);
create table private.platform_admins(user_id uuid primary key, created_at timestamptz not null default now());
alter table private.platform_admins enable row level security;
revoke all on private.platform_admins from public,anon,authenticated;
grant all on private.platform_admins to service_role;
create table private.spend_meter(company_id uuid not null references public.companies(id) on delete cascade,window_start timestamptz not null,spent_minor bigint not null default 0,text_calls int not null default 0,image_calls int not null default 0,primary key(company_id,window_start));
alter table private.spend_meter enable row level security;
revoke all on private.spend_meter from public,anon,authenticated;
grant all on private.spend_meter to service_role;
-- Original reservation cost is retained so refunds survive pricing/month changes.
create table private.ai_charges(id bigint generated always as identity primary key,company_id uuid not null references public.companies(id) on delete cascade,offer_id uuid not null,kind text not null,window_start timestamptz not null,cost_minor int not null,created_at timestamptz not null default now(),refunded boolean not null default false);
alter table private.ai_charges enable row level security;
revoke all on private.ai_charges from public,anon,authenticated;
grant all on private.ai_charges to service_role;
grant usage,select on sequence private.ai_charges_id_seq to service_role;
create index ai_charges_refund on private.ai_charges(company_id,offer_id,kind,id desc) where not refunded;
create function public.is_platform_admin() returns boolean language sql stable security definer set search_path='' as $$select auth.uid() is not null and exists(select 1 from private.platform_admins where user_id=auth.uid())$$;
revoke all on function public.is_platform_admin() from public,anon;
grant execute on function public.is_platform_admin() to authenticated;
create function private.require_active(p_company uuid) returns void language plpgsql security definer set search_path='' as $$begin
 perform 1 from public.companies where id=p_company for update;
 if exists(select 1 from public.companies where id=p_company and access_status='paused') then raise exception 'Acesso pausado pelo OfertaBot' using errcode='42501'; end if;
end$$;
create function private.charge_ai(p_company uuid,p_offer uuid,p_kind text) returns void language plpgsql security definer set search_path='' as $$declare co public.companies; w timestamptz; price int; total bigint; begin
 select * into co from public.companies where id=p_company for update;
 w:=date_trunc('month',now() at time zone co.timezone) at time zone co.timezone;
 price:=case p_kind when 'text' then co.ai_cost_minor else co.image_cost_minor end;
 insert into private.spend_meter(company_id,window_start) values(p_company,w) on conflict do nothing;
 select spent_minor into total from private.spend_meter where company_id=p_company and window_start=w for update;
 if price>0 and co.spend_limit_minor is not null and total+price>co.spend_limit_minor then raise exception 'Limite de gasto mensal atingido'; end if;
 update private.spend_meter set spent_minor=spent_minor+price,text_calls=text_calls+case when p_kind='text' then 1 else 0 end,image_calls=image_calls+case when p_kind='image' then 1 else 0 end where company_id=p_company and window_start=w;
 insert into private.ai_charges(company_id,offer_id,kind,window_start,cost_minor) values(p_company,p_offer,p_kind,w,price);
end$$;
create function private.refund_ai(p_company uuid,p_offer uuid,p_kind text) returns void language plpgsql security definer set search_path='' as $$declare ch private.ai_charges; begin
 perform 1 from public.companies where id=p_company for update;
 select * into ch from private.ai_charges where company_id=p_company and offer_id=p_offer and kind=p_kind and not refunded order by id desc limit 1 for update;
 if not found then return; end if;
 update private.ai_charges set refunded=true where id=ch.id;
 update private.spend_meter set spent_minor=greatest(0,spent_minor-ch.cost_minor),text_calls=greatest(0,text_calls-case when p_kind='text' then 1 else 0 end),image_calls=greatest(0,image_calls-case when p_kind='image' then 1 else 0 end) where company_id=p_company and window_start=ch.window_start;
end$$;
revoke all on function private.require_active(uuid),private.charge_ai(uuid,uuid,text),private.refund_ai(uuid,uuid,text) from public,anon,authenticated;
-- Patch deployed definitions rather than replacing the capture/queue/pagination contract.
do $patch$ declare src text; old text; begin
 select pg_get_functiondef('public.app_action(text,jsonb)'::regprocedure) into src;
 old:='select * into co from public.companies where id=c for update;';
 if strpos(src,old)=0 then raise exception 'app_action guard anchor absent'; end if;
 execute replace(src,old,old||E'\n perform private.require_active(c);');
 select pg_get_functiondef('public.engine_call(text,text,jsonb)'::regprocedure) into src;
 if strpos(src,old)=0 then raise exception 'engine_call guard anchor absent'; end if;
 execute replace(src,old,old||E'\n perform private.require_active(c);');
 select pg_get_functiondef('public.engine_context(text)'::regprocedure) into src;
 old:='return jsonb_build_object(''company_id'',x.company_id,''connection_id'',x.id);';
 if strpos(src,old)=0 then raise exception 'engine_context guard anchor absent'; end if;
 execute replace(src,old,'perform private.require_active(x.company_id); '||old);
 select pg_get_functiondef('public.ai_authorize(uuid,uuid)'::regprocedure) into src;
 src:=replace(src,'perform private.require_role(p_company,array[''owner'',''admin'',''editor'']);','perform private.require_role(p_company,array[''owner'',''admin'',''editor'']); perform private.require_active(p_company);');
 old:='>30 then raise exception ''Limite de 30 reescritas por hora'';';
 if strpos(src,old)=0 then raise exception 'text quota anchor absent'; end if;
 src:=replace(src,old,'>(select ai_hourly_limit from public.companies where id=p_company) then raise exception ''Limite de % reescritas por hora'',(select ai_hourly_limit from public.companies where id=p_company);');
 execute replace(src,'perform private.log(p_company,''ai.requested'',p_offer);','perform private.charge_ai(p_company,p_offer,''text''); perform private.log(p_company,''ai.requested'',p_offer);');
 select pg_get_functiondef('public.ai_authorize_image(uuid,uuid)'::regprocedure) into src;
 src:=replace(src,'perform private.require_role(p_company,array[''owner'',''admin'',''editor'']);','perform private.require_role(p_company,array[''owner'',''admin'',''editor'']); perform private.require_active(p_company);');
 old:='>30 then raise exception ''Limite de 30 imagens com IA por hora atingido'';';
 if strpos(src,old)=0 then raise exception 'image quota anchor absent'; end if;
 src:=replace(src,old,'>(select image_hourly_limit from public.companies where id=p_company) then raise exception ''Limite de % imagens com IA por hora atingido'',(select image_hourly_limit from public.companies where id=p_company);');
 execute replace(src,'perform private.log(p_company,''ai.requested'',p_offer,','perform private.charge_ai(p_company,p_offer,''image''); perform private.log(p_company,''ai.requested'',p_offer,');
 select pg_get_functiondef('public.ai_refund(uuid,uuid)'::regprocedure) into src;
 execute replace(src,'update private.ai_usage','perform private.refund_ai(p_company,p_offer,''text''); update private.ai_usage');
 select pg_get_functiondef('public.ai_refund_image(uuid,uuid)'::regprocedure) into src;
 execute replace(src,'update private.ai_image_usage','perform private.refund_ai(p_company,p_offer,''image''); update private.ai_image_usage');
 select pg_get_functiondef('public.app_snapshot(uuid,text,integer,integer,integer,text)'::regprocedure) into src;
 src:=replace(src,'''companies'',result','''platform_admin'',public.is_platform_admin(),''companies'',result');
 old:='q:=nullif(lower(left(trim(coalesce(p_search,'''')),200)),'''');';
 if strpos(src,old)=0 then raise exception 'snapshot guard anchor absent'; end if;
 execute replace(src,old,E'if exists(select 1 from public.companies where id=c and access_status=''paused'') then return jsonb_build_object(''platform_admin'',public.is_platform_admin(),''companies'',result,''company'',(select to_jsonb(co)||jsonb_build_object(''role'',r) from public.companies co where id=c),''access_paused'',true); end if;\n '||old);
end $patch$;
revoke all on function public.ai_refund(uuid,uuid),public.ai_refund_image(uuid,uuid),public.admin_set_plan(uuid,text,int) from public,anon,authenticated;
grant execute on function public.ai_refund(uuid,uuid),public.ai_refund_image(uuid,uuid),public.admin_set_plan(uuid,text,int) to service_role;
